<?php
declare(strict_types=1);
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/cashier-view.php';require_once __DIR__.'/../includes/live-operations.php';
$user=snc_require_auth(['admin']);$csrfToken=snc_csrf_token();header('Cache-Control: no-store');$error='';$report=null;$filters=['status'=>'all','type'=>'all','page'=>1];
try{$filters=snc_operations_filters($_GET);$report=snc_operations_report(snc_get_db(),$filters);}catch(InvalidArgumentException $e){http_response_code(400);$error=$e->getMessage();}catch(Throwable $e){http_response_code(503);$error='Live Operations is temporarily unavailable. Please refresh to try again.';}
function snc_operations_url(array $changes=[]): string {global $filters;return '?'.http_build_query(array_replace($filters,$changes));}
?>
