<p class="snc-menu-error" id="snc-operations-error" role="alert"><?= snc_cashier_escape($error) ?></p>
<section class="snc-operation-counts" aria-label="All active order counts"><?php foreach(['pending'=>'Pending','preparing'=>'Preparing','ready'=>'Ready'] as $status=>$label): ?><article class="snc-kpi-card"><h2 class="snc-kpi-card__label"><?= $label ?></h2><p class="snc-kpi-card__value" data-operation-count="<?= $status ?>"><?= $report?$report['counts'][$status]:'—' ?></p></article><?php endforeach; ?></section>
<section class="snc-card"><form class="snc-menu-filters" id="snc-operation-filters" method="get"><label>Kitchen status<select name="status"><?php foreach(['all'=>'All Active','pending'=>'Pending','preparing'=>'Preparing','ready'=>'Ready'] as $value=>$label): ?><option value="<?= $value ?>"<?= $filters['status']===$value?' selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>Order type<select name="type"><?php foreach(['all'=>'All Types','dine_in'=>'Dine-In','takeout'=>'Takeout'] as $value=>$label): ?><option value="<?= $value ?>"<?= $filters['type']===$value?' selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><button class="snc-menu-button snc-menu-button--primary" type="submit">Apply Filters</button><a class="snc-menu-button" href="operations.php" data-operations-reset>Reset</a></form><p class="snc-menu-hint">Read-only · oldest orders first · auto-refresh every 10 seconds. Counts cover all active orders, regardless of filters. Pending void requests leave orders active.</p></section>
