<?php endforeach; endif; ?></tbody></table></div><nav class="snc-menu-pagination" id="snc-operations-pagination" aria-label="Active order pages"><?php if($report): foreach([-1=>'Previous',1=>'Next'] as $delta=>$label): $target=$report['page']+$delta;if($target<1||$target>$report['pages'])continue; ?><a class="snc-menu-button" data-operations-page="<?= $target ?>" href="<?= snc_cashier_escape(snc_operations_url(['page'=>$target])) ?>"><?= $label ?></a><?php endforeach; endif; ?></nav></section>
